:root {
  --color-bg: #faf8f4;
  --color-surface: #ffffff;
  --color-text: #2e2e2a;
  --color-text-muted: #5a5a52;
  --color-border: #ddd4c4;
  --color-brand-dark: #2f5d50;
  --color-brand-darker: #203f36;
  --color-accent-on-dark: #cfe8d6;
  --color-focus: #9b6b2c;
  --font-body: Georgia, "Times New Roman", serif;
  --font-display: "Palatino Linotype", "Book Antiqua", Georgia, serif;
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 3rem;
  --radius: 0.5rem;
  --max-width: 75rem;
}

* {
  box-sizing: border-box;
}

html {
  font-size: 100%;
}

body {
  margin: 0;
  font-family: var(--font-body);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
}

h1, h2, h3, h4 {
  font-family: var(--font-display);
  color: var(--color-brand-darker);
  line-height: 1.25;
  margin-top: 0;
}

p {
  margin-top: 0;
}

a {
  color: var(--color-brand-dark);
  text-decoration-thickness: 0.08em;
}

a:hover {
  color: var(--color-brand-darker);
}

a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
}

/* Header */
header {
  background-color: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
  padding-top: var(--space-sm);
  padding-bottom: var(--space-sm);
}

.logo {
  font-family: var(--font-display);
  font-variant: small-caps;
  font-weight: 400;
  letter-spacing: 0.25em;
  font-size: clamp(1rem, 3vw, 1.4rem);
  color: var(--color-brand-dark);
  text-decoration: none;
  border-bottom: 1px solid var(--color-brand-dark);
  width: fit-content;
  padding-bottom: 0.2em;
}

header nav ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin: 0;
  padding: 0;
}

header nav a {
  text-decoration: none;
  color: var(--color-text);
  font-size: 0.95rem;
  padding: 0.5rem 0.25rem;
  display: inline-block;
}

header nav a:hover {
  color: var(--color-brand-dark);
}

/* Footer */
footer {
  background-color: var(--color-brand-darker);
  color: var(--color-accent-on-dark);
  margin-top: var(--space-lg);
}

.footer-inner {
  padding-top: var(--space-md);
  padding-bottom: var(--space-md);
  text-align: center;
}

.footer-logo {
  font-family: var(--font-display);
  font-variant: small-caps;
  letter-spacing: 0.2em;
  font-size: 1.2rem;
  color: #ffffff;
  margin-bottom: var(--space-sm);
}

footer p {
  margin: 0.25rem 0;
  font-size: 0.95rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.75rem 1.5rem;
  background-color: var(--color-brand-dark);
  color: #ffffff;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font-body);
  font-size: 1rem;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.btn:hover {
  background-color: var(--color-brand-darker);
  color: #ffffff;
}

.btn-secondary {
  background-color: var(--color-surface);
  color: var(--color-brand-dark);
  border: 2px solid var(--color-brand-dark);
}

.btn-secondary:hover {
  background-color: var(--color-bg);
  color: var(--color-brand-darker);
}

/* Cards */
.card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--space-md);
}

/* Grid helper */
.grid {
  display: grid;
  gap: var(--space-md);
  grid-template-columns: 1fr;
}

/* Forms */
form {
  display: grid;
  gap: var(--space-sm);
  max-width: 40rem;
}

label {
  display: block;
  font-weight: bold;
  margin-bottom: 0.3rem;
}

input, textarea, select {
  width: 100%;
  min-height: 44px;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  font-family: var(--font-body);
  font-size: 1rem;
  background-color: var(--color-surface);
  color: var(--color-text);
}

textarea {
  min-height: 8rem;
}

.field {
  margin-bottom: var(--space-sm);
}

section {
  padding-top: var(--space-lg);
  padding-bottom: var(--space-lg);
}

.section-alt {
  background-color: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

/* Mobile */
@media (max-width: 600px) {
  .header-inner {
    flex-direction: column;
    align-items: flex-start;
  }

  header nav ul {
    gap: 0.5rem;
  }

  section {
    padding-top: var(--space-md);
    padding-bottom: var(--space-md);
  }

  .grid {
    grid-template-columns: 1fr;
  }
}

/* Desktop */
@media (min-width: 601px) {
  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }

  .grid-auto {
    grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}

