.index-hero {
  padding-top: var(--space-lg);
  padding-bottom: var(--space-lg);
}

.index-hero-inner {
  display: grid;
  gap: var(--space-md);
  align-items: center;
  grid-template-columns: 1fr;
}

.index-hero-text h1 {
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  margin-bottom: var(--space-sm);
}

.index-hero-lede {
  color: var(--color-text-muted);
  font-size: 1.05rem;
  margin-bottom: var(--space-md);
}

.index-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.index-hero-img {
  border-radius: var(--radius);
  width: 100%;
}

.index-quote {
  border-left: 4px solid var(--color-brand-dark);
  margin: 0;
}

.index-quote p {
  font-style: italic;
  margin-bottom: var(--space-sm);
}

.index-quote-author {
  color: var(--color-text-muted);
  font-size: 0.9rem;
}

.index-cta {
  background-color: var(--color-brand-darker);
  color: var(--color-accent-on-dark);
  text-align: center;
}

.index-cta-heading {
  color: #ffffff;
}

.index-cta-text {
  color: var(--color-accent-on-dark);
  max-width: 40rem;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--space-md);
}

.index-cta-btn {
  background-color: #ffffff;
  color: var(--color-brand-darker);
}

.index-cta-btn:hover {
  background-color: var(--color-accent-on-dark);
  color: var(--color-brand-darker);
}

@media (min-width: 601px) {
  .index-hero-inner {
    grid-template-columns: 3fr 2fr;
  }
}

@media (max-width: 600px) {
  .index-hero-actions {
    flex-direction: column;
  }

  .index-hero-actions .btn {
    width: 100%;
  }
}

.schedule-table-wrap {
  overflow-x: auto;
  margin: var(--space-sm) 0;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
}

.schedule-table-grid {
  width: 100%;
  min-width: 36rem;
  border-collapse: collapse;
  background-color: var(--color-surface);
}

.schedule-table-caption {
  caption-side: top;
  text-align: left;
  padding: var(--space-sm);
  font-size: 0.9rem;
  color: var(--color-text-muted);
}

.schedule-table-grid th,
.schedule-table-grid td {
  padding: 0.6rem 0.9rem;
  border-bottom: 1px solid var(--color-border);
  text-align: left;
  white-space: nowrap;
}

.schedule-table-grid thead th {
  background-color: var(--color-brand-dark);
  color: #ffffff;
  font-family: var(--font-display);
}

.schedule-table-grid tbody th[scope="row"] {
  font-weight: bold;
  color: var(--color-brand-darker);
}

.schedule-table-grid tbody tr:nth-child(even) {
  background-color: var(--color-bg);
}

.schedule-note {
  color: var(--color-text-muted);
  font-size: 0.95rem;
  margin-bottom: var(--space-sm);
}

.schedule-type-card h3 {
  margin-bottom: 0.5rem;
}

@media (max-width: 600px) {
  .schedule-table-grid th,
  .schedule-table-grid td {
    padding: 0.5rem 0.6rem;
    font-size: 0.9rem;
  }
}

.teachers-lead {
  max-width: 48rem;
  font-size: 1.15rem;
  color: var(--color-text-muted);
}

.teachers-grid {
  margin-top: var(--space-md);
}

.teachers-card {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.teachers-photo {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  border-radius: var(--radius);
  margin-bottom: var(--space-xs);
}

.teachers-specialty {
  font-weight: bold;
  color: var(--color-brand-dark);
  margin-bottom: var(--space-xs);
}

.teachers-join-inner {
  text-align: center;
  max-width: 40rem;
}

@media (max-width: 600px) {
  .teachers-lead {
    font-size: 1rem;
  }
}

@media (min-width: 601px) {
  .teachers-join-inner {
    margin-left: auto;
    margin-right: auto;
  }
}

.pricing-intro {
  max-width: 42rem;
  color: var(--color-text-muted);
  margin-bottom: var(--space-md);
}

.pricing-grid {
  align-items: stretch;
}

.pricing-card {
  display: flex;
  flex-direction: column;
  position: relative;
}

.pricing-card-featured {
  border-color: var(--color-brand-dark);
  border-width: 2px;
}

.pricing-badge {
  display: inline-block;
  align-self: flex-start;
  background-color: var(--color-brand-dark);
  color: #ffffff;
  font-size: 0.8rem;
  font-weight: bold;
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  margin-bottom: var(--space-sm);
}

.pricing-price {
  font-family: var(--font-display);
  font-size: 2rem;
  color: var(--color-brand-darker);
  margin-bottom: var(--space-xs);
}

.pricing-unit {
  font-size: 1rem;
  font-weight: normal;
  color: var(--color-text-muted);
}

.pricing-desc {
  color: var(--color-text-muted);
  margin-bottom: var(--space-sm);
}

.pricing-features {
  list-style: none;
  padding: 0;
  margin: 0 0 var(--space-md) 0;
  flex-grow: 1;
}

.pricing-features li {
  padding: 0.35rem 0;
  border-bottom: 1px solid var(--color-border);
}

.pricing-features li:last-child {
  border-bottom: none;
}

.pricing-cta {
  margin-top: auto;
  width: 100%;
}

.pricing-note {
  margin-top: var(--space-md);
  font-style: italic;
  color: var(--color-text-muted);
}

.pricing-faq-list {
  display: grid;
  gap: var(--space-sm);
  max-width: 48rem;
}

.pricing-faq-item {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--space-sm) var(--space-md);
}

.pricing-faq-item summary {
  cursor: pointer;
  font-weight: bold;
  font-family: var(--font-display);
  color: var(--color-brand-darker);
  padding: 0.25rem 0;
}

.pricing-faq-item p {
  margin-top: var(--space-xs);
  color: var(--color-text-muted);
}

@media (max-width: 600px) {
  .pricing-price {
    font-size: 1.6rem;
  }

  .pricing-faq-item {
    padding: var(--space-sm);
  }
}

@media (min-width: 601px) {
  .pricing-card-featured {
    transform: translateY(-0.5rem);
  }
}

.contact-info-grid {
  margin-bottom: var(--space-md);
}

.contact-hours-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: var(--space-sm);
}

.contact-hours-table th,
.contact-hours-table td {
  text-align: left;
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--color-border);
  font-weight: normal;
}

.contact-hours-table th {
  color: var(--color-text);
  font-weight: bold;
  padding-right: 1rem;
}

.contact-note {
  color: var(--color-text-muted);
  font-size: 0.95rem;
}

.contact-map {
  margin-top: var(--space-md);
}

.contact-map img {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  width: 100%;
}

@media (max-width: 600px) {
  .contact-details,
  .contact-hours {
    padding: var(--space-sm);
  }
}

